// Generated by npm run feedback:bookmarklet from scripts/lib/gdoc-core.ts. Do not edit by hand.
const LABELS = ['which screen', 'what i did', 'what i expected', 'what happened instead', 'where', 'how much it gets in the way'];
function docIdFrom(urlOrId) {
    const m = /\/document\/d\/([\w-]+)/.exec(urlOrId);
    const id = m?.[1] ?? urlOrId.trim();
    if (!/^[\w-]{20,}$/.test(id))
        throw new Error('that does not look like a Google Doc link or id');
    return id;
}
function titleFrom(line) {
    let t = line.trim().replace(/\s+/g, ' ');
    const stop = t.search(/[.!?](\s|$)/);
    if (stop > 12)
        t = t.slice(0, stop);
    if (t.length > 90)
        t = `${t.slice(0, 90).replace(/\s+\S*$/, '')}…`;
    return t.replace(/[:;,\s]+$/, '');
}
function splitProblems(text) {
    const items = [];
    const start = /^\s*(?:#{1,3}\s+(.+)|(\d+)[.)]\s+(.+))\s*$/;
    for (const line of text.replace(/\\([\\[\]().#*_!-])/g, '$1').split('\n')) {
        const s = start.exec(line);
        if (s !== null && !LABELS.some((l) => line.toLowerCase().includes(`${l}:`))) {
            const n = s[2] !== undefined ? Number(s[2]) : items.length + 1;
            const bodyRaw = (s[1] ?? s[3] ?? '').trim();
            const images = (bodyRaw.match(/\[image\]/gi) ?? []).length;
            const body = bodyRaw.replace(/\[image\]/gi, '').trim();
            items.push({ n, title: s[1] !== undefined ? body.replace(/^\d+[.)]\s*/, '') : titleFrom(body), raw: s[1] !== undefined ? [] : [body], images });
            continue;
        }
        const current = items[items.length - 1];
        if (current === undefined)
            continue;
        const imageCount = (line.match(/\[image\]/gi) ?? []).length;
        current.images += imageCount;
        const cleaned = line.replace(/\[image\]/gi, '').replace(/\\([\\[\]()#.*_-])/g, '$1').trim();
        if (cleaned !== '')
            current.raw.push(cleaned);
    }
    return items.map((it) => {
        const fields = [];
        for (const l of it.raw) {
            const m = /^([^:]{3,40}):\s*(.+)$/.exec(l);
            if (m !== null && LABELS.includes(m[1].trim().toLowerCase().replace(/\*+/g, '')))
                fields.push([m[1].trim().replace(/\*+/g, ''), m[2].trim()]);
        }
        return { n: it.n, title: it.title, lines: it.raw, images: it.images, fields };
    }).filter((it) => it.title !== '' || it.lines.length > 0);
}
function toImporterMarkdown(items, opts) {
    const out = [`# Feedback from ${opts.reporter}: Google Doc ${opts.docId.slice(0, 8)}…, read ${opts.date}`, ''];
    for (const it of items) {
        out.push(`## issue-${String(it.n)}: ${it.title}`, '');
        for (let i = 1; i <= it.images; i++)
            out.push(`![screenshot in the Google Doc, item ${String(it.n)}${it.images > 1 ? `, ${String(i)} of ${String(it.images)}` : ''}](gdoc-item-${String(it.n)}-${String(i)})`);
        if (it.images > 0)
            out.push('');
        out.push(`**Original text (${opts.reporter}):**`);
        const words = it.lines.length > 0 ? it.lines : [it.title];
        for (const l of words)
            out.push(`> ${l}`);
        out.push('');
        if (it.fields.length > 0) {
            out.push('**Summary:**');
            for (const [k, v] of it.fields)
                out.push(`- ${k}: ${v}`);
            out.push('');
        }
        out.push('---', '');
    }
    return out.join('\n');
}
function docJsonToText(doc) {
    const lines = [];
    const counters = new Map();
    for (const el of doc.body?.content ?? []) {
        const p = el.paragraph;
        if (p === undefined)
            continue;
        const text = (p.elements ?? []).map((e) => (e.inlineObjectElement !== undefined ? ' [image] ' : e.textRun?.content ?? '')).join('').replace(/\n+$/, '');
        if (text.trim() === '')
            continue;
        const style = p.paragraphStyle?.namedStyleType ?? '';
        if (/^HEADING_[1-3]$/.test(style)) {
            lines.push(`## ${text.trim()}`);
            continue;
        }
        if (p.bullet !== undefined && (p.bullet.nestingLevel ?? 0) === 0 && p.bullet.listId !== undefined) {
            const glyph = doc.lists?.[p.bullet.listId]?.listProperties?.nestingLevels?.[0]?.glyphType ?? '';
            if (glyph.startsWith('DECIMAL')) {
                const next = (counters.get(p.bullet.listId) ?? 0) + 1;
                counters.set(p.bullet.listId, next);
                lines.push(`${String(next)}. ${text.trim()}`);
                continue;
            }
        }
        lines.push(text.trim());
    }
    return lines.join('\n');
}
function decodeEntities(t) {
    return t.replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
        .replace(/&#39;|&apos;/g, "'").replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
        .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d))).replace(/&amp;/g, '&');
}
function docHtmlToText(html) {
    const at = html.indexOf('doc-content');
    let h = at >= 0 ? html.slice(html.lastIndexOf('<', at)) : html;
    h = h.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '');
    const lines = [];
    const lists = [];
    let cur = '';
    let prefix = '';
    const flush = () => {
        const t = cur.replace(/\s+/g, ' ').trim();
        if (t !== '')
            lines.push(prefix + t);
        cur = '';
        prefix = '';
    };
    const re = /<(\/?)([a-z0-9]+)\b([^>]*)>|([^<]+)/gi;
    for (let m = re.exec(h); m !== null; m = re.exec(h)) {
        if (m[4] !== undefined) {
            cur += decodeEntities(m[4]);
            continue;
        }
        const closing = m[1] === '/';
        const tag = m[2].toLowerCase();
        if (tag === 'ol' || tag === 'ul') {
            flush();
            if (closing)
                lists.pop();
            else
                lists.push({ ordered: tag === 'ol', n: Number(/\bstart="(\d+)"/.exec(m[3] ?? '')?.[1] ?? '1') });
        }
        else if (tag === 'li') {
            flush();
            if (!closing) {
                const l = lists[lists.length - 1];
                prefix = l === undefined ? '' : l.ordered ? `${String(l.n++)}. ` : '- ';
            }
        }
        else if (/^h[1-6]$/.test(tag)) {
            flush();
            if (!closing)
                prefix = '## ';
        }
        else if (tag === 'p' || tag === 'div' || tag === 'br' || tag === 'hr' || tag === 'tr') {
            flush();
        }
        else if (tag === 'img' && !closing) {
            cur += ' [image] ';
        }
    }
    flush();
    return lines.join('\n');
}


(async () => {
  const m = location.pathname.match(/\/document\/d\/([\w-]+)/);
  if (!/(^|\.)docs\.google\.com$/.test(location.hostname) || !m) { alert('Open the Google Doc in this tab first, then run this again.'); return; }
  const id = m[1];
  const res = await fetch('/document/d/' + id + '/mobilebasic', { credentials: 'include' });
  if (!res.ok) { alert('Google answered ' + res.status + '. Are you signed in with an account that may view this doc?'); return; }
  const items = splitProblems(docHtmlToText(await res.text()));
  if (items.length === 0) { alert('No problems found. A problem starts at a numbered line (1. 2. 3.) or a heading.'); return; }
  const reporter = (typeof prompt === 'function' ? prompt('Whose feedback is this? (the name shown on the issues)', 'a tester') : null) || 'a tester';
  const md = toImporterMarkdown(items, { reporter, docId: id, date: new Date().toISOString().slice(0, 10) });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([md], { type: 'text/markdown' }));
  a.download = 'feedback-' + id.slice(0, 8) + '.md';
  document.body.appendChild(a); a.click(); a.remove();
  alert(items.length + ' problem(s) saved as ' + a.download + ' in your Downloads folder.\nNext, in the CRM folder: npm run feedback:latest');
})();
